public class InnerSecurityConfigurationSecurityConfigurationDataFactory(Action<Humidifier.EMRContainers.SecurityConfigurationTypes.SecurityConfigurationData> factoryAction = null) : SubResourceFactory<Humidifier.EMRContainers.SecurityConfigurationTypes.SecurityConfigurationData>
{

    internal InnerSecurityConfigurationAuthenticationConfigurationFactory AuthenticationConfigurationFactory { get; set; }

    internal InnerSecurityConfigurationAuthorizationConfigurationFactory AuthorizationConfigurationFactory { get; set; }

    internal InnerSecurityConfigurationEncryptionConfigurationFactory EncryptionConfigurationFactory { get; set; }

    protected override Humidifier.EMRContainers.SecurityConfigurationTypes.SecurityConfigurationData Create()
    {
        var securityConfigurationDataResult = CreateSecurityConfigurationData();
        factoryAction?.Invoke(securityConfigurationDataResult);

        return securityConfigurationDataResult;
    }

    private Humidifier.EMRContainers.SecurityConfigurationTypes.SecurityConfigurationData CreateSecurityConfigurationData()
    {
        var securityConfigurationDataResult = new Humidifier.EMRContainers.SecurityConfigurationTypes.SecurityConfigurationData();

        return securityConfigurationDataResult;
    }
    public override void CreateChildren(Humidifier.EMRContainers.SecurityConfigurationTypes.SecurityConfigurationData result)
    {
        base.CreateChildren(result);

        result.AuthenticationConfiguration ??= AuthenticationConfigurationFactory?.Build();
        result.AuthorizationConfiguration ??= AuthorizationConfigurationFactory?.Build();
        result.EncryptionConfiguration ??= EncryptionConfigurationFactory?.Build();
    }

} // End Of Class

